BATCH = {
(28,42):{'topic':'placentaAccretaSpectrum','lead':'نفوذ جفت به جدار مثانه حین سزارین در سابقهٔ دو سزارین: جفت Percreta (عمیق‌ترین نوع سندرم آکره‌تا).',
'interpretation':'در طیف چسبندگی جفت، آکره‌تا چسبندگی به میومتر بدون نفوذ است، اینکره‌تا نفوذ به داخل میومتر و پرکره‌تا نفوذ از سروزا گذشته و به ارگان‌های مجاور مثل مثانه است؛ یافتهٔ حین عمل (نفوذ به مثانه) مستقیماً به مرحلهٔ پرکره‌تا اشاره دارد و عامل زمینه‌ای اصلی (چند سزارین قبلی) این طیف را برای خون‌ریزی‌های هول‌انگیز حین تخلیهٔ جفت آماده می‌کند.',
'reasons':['آکره‌تا فقط چسبندگی سطحی جفت به میومتر است و به مثانه نمی‌رسد.','اینکره‌تا به عمق میومتر نفوذ می‌کند ولی از سروزا عبور نمی‌کند.','نفوذ فراسرراهی به مثانه تعریف پرکره‌تا است؛ پاسخ صحیح.','نفوذ ویلامنتوس اصطلاح پرواندیش بند ناف است نه چسبندگی جفت.']},
(28,43):{'topic':'pphProstaglandinSide','lead':'تب و تهوع و استفراغ پس از تزریق PGF2a (کاربوپروست) در خون‌ریزی پس از زایمان مهارشده: شایع‌ترین تفسیر این ترکیب، عارضهٔ داروی پروستاگلاندین است.',
'interpretation':'کاربوپروست (پروستاگلاندین F2 آلفا) موجب انقباض قوی رحم برای کنترل آتونی می‌شود ولی عوارض دستگاه گوارش (تهوع، استفراغ، اسهال) و تب عابر از عوارض شناخته‌شدهٔ اوست که معمولاً با درمان حمایتی (ضدتهوع، مایعات) کنترل می‌شود؛ در این سناریو علائم بعد از تجویز دارو ظاهر شده و شواهدی برای عفونت (مانند ترشح بدبو) یا پره‌اکلمپسی پس از زایمان (فشار بالا/پروتئینوری/علایم عصبی) مطرح نیست؛ با فشار ۱۳۰/۷۰ پره‌اکلمپسی در حد مطرح نیست.',
'reasons':['پره‌اکلمپسی با فشار ۱۳۰/۷۰ و بدون علایم عصبی/پروتئینوری این‌جا مطرح نیست.','مترژین بیش‌تر افزایش فشار ایجاد می‌کند نه تب و عوارض گوارشی بارز.','تهوع، استفراغ و تب عابر عوارض شایع پروستاگلاندین است و درمان حمایتی کافی است؛ پاسخ صحیح.','بدون ترشح بدبو یا تندرنس، پروسهٔ عفونی در صدر نیست.']},
(28,44):{'topic':'preeclampsiaTwinsDelivery','lead':'دوقلویی ۳۷ هفته با پره‌اکلمپسی (۱۴۰/۹۰ + پروتئینوری ۱+): ترم رسیده و ختم بارداری شایسته است.',
'interpretation':'در پره‌اکلمپسی پس از ۳۷ هفته، مدیریت قطعی ختم بارداری است چون نگه‌داشتن بارداری هم در دوقلویی و هم در پره‌اکلمپسی به خطر مادر/جنین است و در حالت موجود هیچ علت مؤید برای تعلل نیست؛ کورتون در این سن دیگر تغییردهندهٔ تصمیم نیست و «پایش تا ۳۸ هفته یا پروفایل هفتگی» فقط برای بیمار بدون پره‌اکلمپسی است، نه بیمار پره‌اکلمپسی ترم.',
'reasons':['ختم بارداری در پره‌اکلمپسی ترم دوقلویی درست است؛ پاسخ صحیح.','ادامهٔ بارداری تا ۳۸ هفته در پره‌اکلمپسی خطر را افزایش می‌دهد.','کورتون در ۳۷ هفته برای بلوغ ریه لازم نیست و ختم را به تأخیر می‌اندازد.','پروفایل هفتگی در پره‌اکلمپسی ترم جای ختم را نمی‌گیرد.']},
(28,45):{'topic':'migrainePregSafest','lead':'در حملهٔ میگرن بارداری ۳۴ هفته، کم‌عارضه‌ترین گزینهٔ این فهرست استامینوفن-کدئین (ترکیب استامینوفن با دوز پایین مخدر) است.',
'interpretation':'دروس حمله‌ای میگرن در بارداری باید با حداقل اثر بر جنین انتخاب شوند: ایبوپروفن و ایندومتاسین (داروهای ضدالتهاب غیراستروئیدی) در سه‌ماههٔ سوم به‌خاطر بستن دوکتوس آرتریوزوس و الیگوهیدرامنیوس ممنوع یا بسیار محدودند و ارگوتامین ممنوع مطلق است؛ در بین این چهار گزینه، استامینوفن-کدئین به‌کار رفتنِ موقتی و با دوز کوتاه نسبت به گزینه‌های دیگر اثر جنینی کمتری دارد و در راهنمای بالینی همین توصیه است.',
'reasons':['ایبوپروفن در سه‌ماههٔ سوم به‌دلیل اثر بر دوکتوس و مایع آمنیوتیک محدود است.','استامینوفن-کدئین با کم‌ترین اثر جنینی در میان این فهرست است؛ پاسخ صحیح.','ایندومتاسین در سه‌ماههٔ سوم ممنوع است (بستن دوکتوس).','ارگوتامین به‌دلیل اثر انقباض‌دهندگی رحمی در بارداری ممنوع مطلق است.']},
(28,46):{'topic':'prematureOvarianInsufficiency','lead':'آمنورهٔ ثانویه با استرادیول پایین و FSH=۳۵ و عدم خون‌ریزی پس‌از-پروژسترون: نارسایی اولیهٔ تخمدان (POI).',
'interpretation':'افزایش FSH (بالاتر از ۲۵-۴۰) همراه با کاهش استرادیول یعنی تخمدان به تحریک گنادوتروپینی پاسخ نمی‌دهد (نارسایی اولیهٔ/زودرس) و نبود خون‌ریزی پس از پروژسترون نشانهٔ فارغ‌نبودن استروژن مناسب برای آماده‌سازی آندومتر است؛ آشرمن با FSH طبیعی می‌آید (بلوغ طبیعی استروژنی)، PCOS با FSH طبیعی یا پایین و استرادیول طبیعی همراه است و اختلال عملکرد هیپوتالاموس-هیپوفیز FSH پایین می‌دهد نه ۳۵.',
'reasons':['آشرمن با فقدان تخمک‌گذاری اما استروژن و FSH طبیعی می‌آید و متن سابقهٔ کورتاژ می‌خواهد.','استرادیول پایین + FSH بالا قاعدهٔ کلاسیک نارسایی تخمدان است؛ پاسخ صحیح.','PCOS با استرادیول طبیعی و FSH طبیعی/پایین می‌آید.','اختلال هیپوتالاموس-هیپوفیز با FSH پایین و LH پایین می‌آید.']},
(28,47):{'topic':'earlyPregSerialHcg','lead':'تأخیر پریود + درد زیرشکم و خون‌ریزی خفیف با علائم حیاتی پایدار و سونوگرافی ناقطع: BHCG سریالی ۴۸ ساعت بعد.',
'interpretation':'تشخیص بارداری با محل نامعلوم در بیمار پایدار با هر دو احتمال بارداری طبیعی اولیه و EP نمی‌تواند با یک سونوگرافی بسته شود؛ ابزار اولیهٔ قوی، روند BHCG در ۴۸ ساعت است: در بارداری داخل‌رحمی سالم معمولاً حداقل ~۵۰-۶۳٪ صعود دیده می‌شود و نبود روند فزایندهٔ مورد انتظار برای EP هشدار است؛ سونوگرافی هفتهٔ بعد اگر BHCG ناحیهٔ تفکیک را رد کند انجام می‌شود نه به‌عنوان قدم اول؛ کورتاژ تشخیصی تهاجمی است و پروژسترون جایگاه پیشگیری ندارد.',
'reasons':['تیتراژ مجدد BHCG چهل‌وهشت ساعت بعد گام استاندارد اول است؛ پاسخ صحیح.','سونوگرافی یک هفته بعد فقط در صورت عبور BHCG از آستانهٔ تشخیص انجام می‌شود.','کورتاژ تشخیصی در بیمار پایدار بدون تأیید عدم‌قطعیت بدن درست نیست.','پروژسترون برای جلوگیری از سقط در این اندازه‌شناسی مؤید نیست.']},
(28,48):{'topic':'solidOvarianMassYoung','lead':'تودهٔ توپر (سولید) تخمدان حتی در زنان جوان: تا روشن نشدن ماهیت، ارزیابی جراحی لازم است و در این کلید لاپاروتومی انتخاب است.',
'interpretation':'کیست‌های ساده عملیاتی تخمدان در زنان جوان معمولاً با پیگیری سونوگرافیک مدیریت می‌شوند، اما تودهٔ «توپر/سولید» هر اندازه‌ای که باشد از منظر احتمال تومورهای سلول جنینی/استرومایی یا آندمینیوما اهمیت دارد و صرف پیگیری یا قرص‌خوراکی کردن کافی نیست؛ بیوپسی هدایت‌شده با سونوگرافی در تودهٔ سولید تخمدانی به‌خاطر خطر پخش بذر توصیه نمی‌شود و انتخاب کلیدی این پرسش لاپاروتومی برای ارزیابی/استخراج است.',
'reasons':['بیوپسی با گاید سونوگرافی در تودهٔ تخمدان به‌علت خطر پخش توصیه نمی‌شود.','قرص ضدبارداری+پیگیری برای تودهٔ سولید کافی نیست.','تکرار صرف سونوگرافی دو ماه بعد در تودهٔ سولید تصمیم را به تأخیر می‌اندازد.','ارزیابی جراحی (لاپاروتومی) در تودهٔ سولید تخمدان درست است؛ پاسخ صحیح.']},
(28,49):{'topic':'postMolarFollow','lead':'پس از تخلیهٔ مول، توصیهٔ کلاسیک: اجازهٔ بارداری ۶ ماه پس از منفی‌شدن BHCG سرم (با کنترل هفتگی تا منفی، سپس ماهانه در بازهٔ پایش).',
'interpretation':'پس از مول کامل/جزئی، مهم‌ترین مانع بارداری زودهنگام، پنهان‌ماندن عود به شکل GTN است چون BHCG بارداری جدید با BHCG عود اشتباه می‌شود؛ راهنمای قدیم/متعارف ایران «۶ ماه پس از منفی‌شدن BHCG» است پس از آن که پایش هفتگی تا منفی و سپس ماهانه ادامه‌دار است. پیش‌گیری‌زدایی (مثلاً ۶ ماه از زمان کورتاژ بدون اتکا به منفی شدن) مبنای درستی ندارد و یک سال پس از منفی شدن در اکثر راهنماها محافظه‌کارانه است.',
'reasons':['۶ ماه پس از کورتاژ بدون توجه به نتیجهٔ BHCG مبنای درستی نیست.','۶ ماه پس از منفی‌شدن BHCG توصیهٔ استاندارد است؛ پاسخ صحیح.','یک سال پس از کورتاژ بدون پایهٔ BHCG معیار نیست.','یک سال پس از منفی‌شدن BHCG محافظه‌کارانه‌تر از متن این کلید است.']},
(28,51):{'topic':'pcosFutureComplications','lead':'PCOS خطر سرطان آندومتر، دیابت نوع دو و بیماری قلبی‌عروقی را بالا می‌برد؛ نارسایی کلیوی جزء عوارض موردانتظار آن نیست.',
'interpretation':'سندرم تخمدان پلی‌کیستیک با آنولاسیون مزمن و مقاومت انسولینی همراه است و بیمار را در برابر دیابت نوع ۲، سندرم متابولیک و بیماری قلبی‌عروقی آسیب‌پذیر می‌کند و به‌دلیل قرار گرفتن مزمن آندومتر زیر اثر استروژن بدون پروژسترون، خطر هیپرپلازی/سرطان آندومتر افزایش می‌یابد؛ آسیب کلیوی مزمن جزو پیامدهای مستقیم و شایع PCOS نیست و نباید در این فهرست قرار داشته باشد.',
'reasons':['بیماری قلبی‌عروقی از عوارض دیررس مرتبط با PCOS است.','دیابت نوع ۲ از عوارض متابولیک رایج PCOS است.','نارسایی کلیوی جزء عوارض مستقیم شایع PCOS نیست؛ پاسخ صحیح.','سرطان آندومتر به‌دلیل تحریک استروژنی بدون مقابل در PCOS بیش‌تر می‌شود.']},
(28,52):{'topic':'papEndometrialCellsPmp','lead':'مشاهدهٔ سلول‌های آندومتری در پاپ‌اسمیر زن یائسه‌ای که خون‌ریزی هم ندارد: باید برای بدخیمی آندومتر بررسی شود تا قطعی رد شود.',
'interpretation':'سلول‌های آندومتری خوش‌ظاهر در پاپ‌اسمیر زنان بالای ۴۵ سال/یائسه به‌خودی‌خود «نرمال» تلقی نمی‌شود و می‌تواند آینهٔ هایپرپلازی/بدخیمی آندومتر یا حتی نشت ضایعهٔ لوله/تخمدان باشد؛ بنابراین بررسی بیمار از منظر سرطان آندومتر (سونوگرافی اندازهٔ گیری لایه و در صورت لزوم بیوپسی) توصیه می‌شود، نه صرف تکرار پاپ‌اسمیر یا کولپوسکوپی یا تست HPV که ابزارهای سرطان سرویکس‌اند.',
'reasons':['کولپوسکوپی برای ارزیابی سرویکس است نه سلول‌های آندومتری مشاهده‌شده.','تکرار پاپ‌اسمیر بدون ارزیابی آندومتر در یائسه تصمیم‌ساز نیست.','بررسی برای سرطان آندومتر (سونوگرافی/بیوپسی در صورت لزوم) درست است؛ پاسخ صحیح.','تست HPV برای بررسی دهانهٔ رحم است و وضعیت آندومتری را روشن نمی‌کند.']},
(28,53):{'topic':'gdmPostpartumTest','lead':'پس از بارداری با GDM (مثبت در دو مرحله), در ویزیت پس‌از‌زایمان تست OGTT دو‌ساعته با ۷۵ گرم گلوکز توصیه می‌شود تا دیابت پایدار رد شود.',
'interpretation':'زنانی که دیابت حاملگی داشته‌اند در ۴-۱۲ هفتهٔ پس از زایمان باید با آزمون تحمل گلوکز خوراکی دو ساعته با دوز ۷۵ گرم (همان آزمون غربالگری دیابت بزرگسال) رد شوند تا ریسک تبدیل به دیابت نوع دو مشخص شود؛ تکرار تست ۵۰ گرمی یا OGTT سه‌ساعتهٔ بارداری در دوران نفاس جایگاه ویژه ندارد و HbA1c به‌تنهایی ممکن است نرمال‌نمای باشد و OGTT دو ساعته به دلیل تشخیص کاهش تحمل گلوکز مقدم‌تر است.',
'reasons':['OGTT سه‌ساعتهٔ بارداری در نفاس لازم نیست.','تست ۵۰ گرمی غربالگری دیابت بارداری است و در دوران نفاس کاربرد متعارف ندارد.','OGTT دو ساعتهٔ ۷۵ گرمی پس از زایمان درست است؛ پاسخ صحیح.','HbA1c به‌تنهایی در رد کاهش تحمل گلوکز پساز-زایمان کافی نیست و جای OGTT را نمی‌گیرد.']},
(28,54):{'topic':'papStartIran','lead':'برای زنی که ۳ سال پیش وارد زندگی زناشویی شده، پاپ‌اسمیر از هم‌اکنون طبق برنامهٔ غربالگری (سه سال پس از آغاز مقاربت) توصیه می‌شود.',
'interpretation':'برنامهٔ غربالگری سرطان دهانهٔ رحم شروع پاپ‌اسمیر را سه سال پس از آغاز فعالیت جنسی منظم (یا ازدواج) می‌داند؛ این بیمار ۱۷ ساله با سه سال ازدواج از هم‌اکنون کاندید غربالگری است؛ آستانهٔ ۱۸ سالگی و «پس از اولین زایمان» مبانی قدیمی یا نامربوط‌اند و ۳۰ سالگی مبنای تغییر نوع تست (افزودن HPV co-test) است نه نقطهٔ شروع غربالگری در چنین بیماری.',
'reasons':['۱۸ سالگی استاندارد فعلی شروع به‌تنهایی نیست.','۳۰ سالگی نقطهٔ تغییر روش غربالگری است نه شروع آن.','سه سال ازدواج یعنی هم‌اکنون شروع پاپ‌اسمیر؛ پاسخ صحیح.','پس از اولین زایمان ملاک شروع غربالگری نیست.']},
(28,56):{'topic':'inevitableAbortion','lead':'خون‌ریزی و درد کولیکی ۱۲ هفته با خروج ترشح آبکی از دهانهٔ سرویکس: پرده پاره است و سقط اجتناب‌ناپذیر جریان دارد.',
'interpretation':'هرگاه علایم خون‌ریزی و درد سه‌ماههٔ اول با مشاهدهٔ دهانهٔ باز یا خروج محتویات/ترشح آبکی (پارگی پرده) از دهانهٔ سرویکس همراه شود، امکان پیش‌گیری از سقط وجود ندارد و فرایند «اجتناب‌ناپذیر» نامیده می‌شود؛ تهدید به سقط با دهانهٔ بسته و پردهٔ سالم می‌آید، سقط فراموش‌شده جنین بدون علایم خروج است و سقط کامل یعنی تخلیهٔ کامل محتویات که هنوز رخ نداده‌است.',
'reasons':['تهدید به سقط با دهانهٔ سرویکس بسته و پردهٔ سالم تعریف می‌شود.','سقط فراموش‌شده در غیاب علایم خروج تعریف می‌شود.','سقط کامل یعنی همهٔ محتویات خارج شده‌اند که در اینجا فقط شروع خروج است.','دهانهٔ باز با خروج ترشح آبکی تعریف سقط اجتناب‌ناپذیر است؛ پاسخ صحیح.']},
(28,58):{'topic':'severePreeclampsiaFeatures','lead':'فشار ۱۴0/80 + پلاکت ۹۰٬۰۰۰ + AST=۷۶ در ۳۴ هفته: این ترکیب ملاک‌های پره‌اکلمپسی با علایم شدید را دارد و اقدام درست سولفات منیزیم و ختم بارداری است.',
'interpretation':'هر یک از موارد «تکرومبوسیتوپنی کمتر از ۱۰۰ هزار»، «افزایش AST/ALT بیش از دو برابر حد طبیعی» و «فشار بالای ۱۶۰/۱۱۰» به‌تنهایی بیماری را به‌صورت «علایم شدید» تعریف می‌کند و در ۳۴ هفتهٔ بارداری ختم با پوشش پیشگیری از تشنج (سولفات منیزیم) استاندارد است؛ کورتون را می‌توان همراه داد ولی تفسیر «انتظار تا ۳۷ هفته» در علایم شدید پذیرفتنی نیست و داپلر شریان نافی در این شرایط تصمیم‌ساز اصلی نیست.',
'reasons':['در علایم شدید تاخیر در ختم خطرناک است و کورتون به‌تنهایی کافی نیست.','داپلر شریان نافی ارزیابی مکمل است نه تصمیم ختم.','علایم شدید دارد و سولفات + ختم درست است؛ پاسخ صحیح.','نگه‌داشتن تا ۳۷ هفته در علایم شدید اشتباه است.']},
(28,59):{'topic':'eclampsiaMgFirst','lead':'تشنج تونیک-کلونیک + فشار ۱۸۰/۱۲۰ در ۳۳ هفتهٔ بارداری: تشخیص اکلمپسی و داروی خط اول، سولفات منیزیم (برای مهار و پیشگیری از عود تشنج).',
'interpretation':'اکلمپسی تا زمان اثبات عکس هر تشنج در سه‌ماههٔ سوم بارداری مدیریت می‌شود و داروی انتخابی اولیه، سولفات منیزیم است چون بهتر از فنی‌توئین و دیازپام تشنج را کنترل و از عود پیشگیری می‌کند؛ انتوباسیون فقط در آپنه/ناکامی تنفسی است و همهٔ اکلمپسی‌ها خودبه‌خود نیازندارند، خوابیدن به‌پشت فشار رحم به ورید اجوف را بدتر می‌کند (وضعیت چپ‌پهلو بهتر است) و کورتون+ختم پس از پایدارشدن مادر است، نه به‌جای مهار تشنج.',
'reasons':['انتوباسیون روتین اکلمپسی نیست و فقط در ناکامی تنفسی مؤید است.','وضعیت درازکش به‌پشت فشار به ورید اجوف را زیاد می‌کند؛ چپ‌پهلو ترجیح دارد.','شروع سولفات منیزیم اقدام خط اول اکلمپسی است؛ پاسخ صحیح.','کورتون و ختم پس از پایدارشدن مادر انجام می‌شود نه به‌جای مهار تشنج.']},
(28,60):{'topic':'labetalolAsthmaPreeclampsia','lead':'در بیمار آسمیک با پره‌اکلمپسی شدید، لبتالول (بلوک‌کنندهٔ بتا) به‌دلیل خطر برونکواسپاسم انتخاب نامناسب است؛ هیدرالازین، نیفی‌دیپین و NTG مجازند.',
'interpretation':'در اورژانس فشارخون دوران بارداری، هیدرالازین/لبتالول/نیفی‌دیپین از داروهای رایج‌اند و تری‌نیتروگلیسیرین نیز در موارد خاص مصرف می‌شود اما بیماری که آسم فعال یا اخیر دارد به‌خاطر اثر بتابلاک‌کنندهٔ لبتالول در معرض برونکواسپاسم قرار می‌گیرد و این دارو در آن‌ها نسبتاً ممنوع است؛ بنابراین در این فهرست «جزء»، لبتالول است.',
'reasons':['هیدرالازین در اورژانس فشار بارداری مجاز است.','لبتالول با آسم فعال منع نسبی دارد؛ پاسخ صحیح (استثنا).','نیفی‌دیپین خوراکی در اورژانس فشار بارداری بکار می‌رود.','نیتروگلیسیرین در موارد خاص قابل‌استفاده است.']},
(28,61):{'topic':'periodontalPreterm','lead':'بیماری پریودنتال در بارداری با خطر زایمان زودرس (پرترم لیبر) بیش‌ترین ارتباط را دارد.',
'interpretation':'التهاب مزمن لثه/دندان به‌خاطر بار میکروبی و التهاب سیستمیک، با افزایش سیتوکین‌ها و پروستاگلاندین‌ها پیوند خورده و در مطالعات اپیدمیولوژیک شایع‌ترین عارضهٔ مرتبط بارداری آن، زایمان زودرس است؛ اثر بر رشد داخل‌رحمی یا پارگی زودرس پرده‌ها به‌مراتب کم‌تواتر و کم‌استدلال‌تر است و الیگوهیدرامنیوس+مرگ داخل‌رحمی پیامد شدید و نادر است.',
'reasons':['زایمان زودرس محتمل‌ترین عارضهٔ مرتبط با بیماری پریودنتال در بارداری است؛ پاسخ صحیح.','محدودیت رشد داخل‌رحمی ارتباط شایع‌تری با عوامل جفت/فشار دارد.','پارگی زودرس پرده ارتباط کمتری با پریودنتال دارد.','الیگوهیدرامنیوس و مرگ داخل‌رحمی پیامد شدید و نادر این تعامل است.']},
(28,62):{'topic':'myomaAsymptomaticObserve','lead':'میوم‌های کوچک (۲-۴ سانتی‌متر) بدون‌علامت در زن ۴۰ سالهٔ مولتی‌پار: نیاز به اقدام درمانی نیست و پایش/اطمینان‌بخشی معقول اوست.',
'interpretation':'با غلبهٔ سابقهٔ کیست تخمدان منقضی و تخمدان‌های طبیعی فعلی، سه میوم کوچک دیواره‌ای/ساب‌سروزال در غیاب علایم مثل منورراژی، درد یا اثر فشاری، صرفاً یافته‌های تصادفی‌اند و درمان‌های تهاجمی (هیسترکتومی یا میومکتومی) توجیه ندارند و OCP نیز برای میوم محض درمان نیست؛ رویکرد مناسب، مشاهده و پیگیری بالینی-سونوگرافیک بر اساس علایم است.',
'reasons':['هیسترکتومی در میوم بدون‌علامت کوچک افراط درمانی است.','میومکتومی برای میوم‌های خفیف بدون‌علامت لازم نیست.','قرص ترکیبی برای میوم بدون‌علامت ضرورتی ندارد و فقط در علایم خون‌ریزی فکر می‌شود.','بدون علامت+اندازه کوچک یعنی فقط نظارت؛ پاسخ صحیح.']},
(28,63):{'topic':'sfhBelowBiometry','lead':'اختلاف قابل‌توجه ارتفاع رحم با سن بارداری (۲۸ سانتی‌متر به‌جای حدود ۳۲ در ۳۲ هفته): قدم اول سونوگرافی بیومتری برای سنجش رشد جنین.',
'interpretation':'سن سمفیز-فوندوس در قاعدهٔ تقریبی باید با هفتهٔ بارداری مطابقت داشته باشد (±۳ سانتی‌متر)؛ اختلاف ۴ سانتی‌متری یا بیش‌تر هشدار برای محدودیت رشد داخل‌رحمی یا خطای تاریخ است و ارزیابی متوالی با سونوگرافی اندازه‌گیری (بیومتری+تیمین آب آمنیوتیک) شروع می‌شود تا IUGR تفکیک شود؛ داپلر شریان نافی مرحلهٔ بعدی است و بیوفیزیکال پروفایل پس از مستندشدن مشکل رشد کاربرد دارد و مراقبت روتین در این اندازه خطا می‌ایستد.',
'reasons':['داپلر شریان نافی گام بعد پس از مستندشدن IUGR در بیومتری است.','سونوگرافی بیومتری اولین اقدام در اختلاف ارتفاع رحم با سن است؛ پاسخ صحیح.','بیوفیزیکال پروفایل برای پایش بیمار مستندشدهٔ IUGR کاربرد دارد نه به‌عنوان قدم اول.','ادامهٔ مراقبت روتین این اختلاف را نادیده می‌گیرد.']},
(28,64):{'topic':'postdatesInduceFavourable','lead':'۴1 هفتهٔ بارداری با گزارش کاهش حرکات جنین و سرویکس مطلوب (آماده): القای زایمان درست‌تر از NST/BPP دوباره یا سزارین بی‌دلیل است.',
'interpretation':'در بارداری پس‌ازترم (٤١ هفته و بیش‌تر) با شرایط سرویکس کامل (نرم، قدامی، افاسمان بالا) و گزارش مادر از کاهش حرکات جنین — که به‌خودی‌خود هشدار است — القای زایمان منطقی‌ترین اقدام است چون ریسک ادامهٔ بارداری از ترم گذشته است؛ سونوگرافی و NST در این وضعیت گزارش‌دهندهٔ وضع لحظه‌ای‌اند ولی در منطق کلید، با سرویکس مطلوب نباید تصمیم معوق شود و سزارین بدون علت اضافه انجام نمی‌شود.',
'reasons':['انجام NST و سونوگرافی در کاهش حرکات همراه سن گذشته و سرویکس مطلوب آن‌قدر محافظه‌کارانه نیست که ختم را به تأخیر بیندازد.','القای زایمان با سرویکس مطلوب در این نقطه درست است؛ پاسخ صحیح.','سزارین اورژانسی بدون دیسترس یا علت اضافی لازم نیست.','درخواست BPP در شرایط سرویکس مطلوب و کاهش حرکات، گزینهٔ مرجع نیست.']},
(28,65):{'topic':'hrtImmobilizationVte','lead':'شکستگی لگن و بی‌حرکتی طولانی در مصرف‌کنندهٔ HRT: اصلاح ریسک ترومبوآمبولی با پروفیلاکسی (به‌مرور با پزشک دربارهٔ HRT نیز تصمیم شود).',
'interpretation':'بی‌حرکتی پیران شکستگی لگن، ترومبوآمبولی وریدی را به‌طور چشم‌گیری بالا می‌برد و HRT نیز ریسک افزوده است؛ در این شرایط اقدام پذیرفته‌شدهٔ فوری، پروفیلاکسی دارویی-مکانیکی ترومبوآمبولی است و نه هیپارین دوز درمانی که برای ترومب تشکیل‌شده است و فدایی HRT یا OCP نیز در این نقطهٔ فوریت مضحک است و «بدون اقدام» در این ریسک بالا پذیرفتنی نیست.',
'reasons':['دوز درمانی هپارین برای ترومبوآمبولی اثبات‌شده است نه پروفیلاکسی.','پروفیلاکسی ترومبوآمبولی اقدام درست در بی‌حرکتی است؛ پاسخ صحیح.','قطع HRT و شروع OCP در این زمینه مناسب نیست (هر دو ریسک افزوده‌اند).','بدون اقدام در ریسک بالای بی‌حرکتی قابل‌قبول نیست.']},
(28,67):{'topic':'pyeloPersistingFeverImaging','lead':'پیلونفریت بارداری با تب مداوم بیش از ۴۸ ساعت علی‌رغم آنتی‌بیوتیک مناسب: سونوگرافی کلیه‌ها برای رد آبسهٔ کلیوی/پرینفریک یا انسداد.',
'interpretation':'در پیلونفریت حاد بارداری انتظار می‌رود تب ظرف ۴۸-۷۲ ساعت از شروع آنتی‌بیوتیک مناسب فروکش کند؛ تداوم تب به‌معنای امکان آناتومی غیرعادی، انسداد سنگ، آبسهٔ کلیوی/پرینفریک یا مقاومت میکروبی است و اولین قدم ارزیابی تصویری (سونوگرافی کلیه و مجاری) است؛ تعویض تجربی آنتی‌بیوتیک قبل از بررسی علل ساختاری دیرخاست است و تکرار آزمایش ادرار به‌تنهایی تصمیم‌ساز نیست و ادامهٔ همان درمان بدون ارزیابی خطر سپسیس را زیاد می‌کند.',
'reasons':['ادامهٔ همان درمان بدون ارزیابی ریسک آبسه/انسداد را ازدست می‌دهد.','تعویض آنتی‌بیوتیک بدون بررسی علل ساختاری گام زودهنگام است.','سونوگرافی کلیه‌ها در تب مداوم پیلونفریت اقدام صحیح است؛ پاسخ صحیح.','تکرار آزمایش ادرار به‌خودی‌خود تصمیم را تغییر نمی‌دهد.']},
(28,68):{'topic':'postMolarFollow','lead':'حتی پس از هیسترکتومی برای مول کامل، چون سلول‌های تروفوبلاست گردش‌خون باقی می‌مانند، چک سری BHCG هفتگی تا منفی و سپس طی دورهٔ پایش لازم است.',
'interpretation':'هیسترکتومی رحم را می‌برد ولی از شکل‌گیری GTN در سایت‌های دور جلوگیری نمی‌کند و خطر عود به‌ویژه در مول کامل باقی است؛ تنها تست مؤید برای پیگیری، تیتر BHCG (هفتگی تا منفی شدن و سپس بر اساس پروتکل ماهانه) است؛ پرولاکتین و سونوگرافی ماهانه یا عدم پیگیری، هیچ‌کدام قاعدهٔ پایش نئوپلازی تروفوبلاستیک را رعایت نمی‌کنند.',
'reasons':['چک BHCG هفتگی ستون پیگیری پس‌از-مول است؛ پاسخ صحیح.','پرولاکتین در پایش بیماری تروفوبلاستیک نقش کلینیکی ندارد.','سونوگرافی ماهانه جای تیتر BHCG را نمی‌گیرد.','چشم‌پوشی از پایش در مول کامل به‌خاطر خطر بالای GTN خطرناک است.']},
(28,69):{'topic':'bvDiagnosis','lead':'ترشح همگن سفید + pH>۴٫۵ + سلول‌های سرنخ (clue) بالای ۲۰٪ در میکروسکوپی: تشخیص بالینی واژینوز باکتریال (BV).',
'interpretation':'معیار امسل برای BV دست‌کم سه مورد از چهار: ترشح سفید همگن چسبیده به دیوارهٔ واژن، pH>۴٫۵، بوی ماهی با اضافه‌شدن هیدروکسید پتاسیم و سلول‌های سرنخ (clue) در بیش از ۲۰٪ سلول‌های اپیتلیال؛ در این بیمار حداقل سه معیار صراحتاً رعایت شده و تشخیص بالینی BV است؛ کاندیدیاز pH نرمال و خیار و پوسیده رنگ دارد، تریکوموناز سلول clue ندارد و واژینیت آتروفیک در زنان ۴۰ سالهٔ پری‌منوپوزال با این یافته‌ها در صدر نیست.',
'reasons':['کاندیدیاز با ترشح پنیری و pH نرمال (٤٫۵ یا کم‌تر) می‌آید نه سلول سرنخ.','این سه‌معم‌خته معیار امسل را برای BV تأمین می‌کند؛ پاسخ صحیح.','تریکوموناز با الواتر و pH بالا ولی سلول سرنخ ندارد و تریکوموناد متحرک در وت‌مونت دیده می‌شود.','واژینیت آتروفیک در این سن با این مشخصه‌ها مطرح نیست.']},
(28,70):{'topic':'aisSyndrome','lead':'46XY + بلوغ پستانی طبیعی + موهای شرمگاهی بسیار‌کم + واژن بستهٔ کوتاه + تودهٔ دوطرفه در کانال اینگوینال: سندرم نبود حساسیت به آندروژن (AIS).',
'interpretation':'در سندرم نگاه‌نبودن به آندروژن (با کاریوتایپ 46XY) گیرندهٔ آندروژن کار نمی‌کند و تستوسترون بالا به استروژن تبدیل می‌شود و بلوغ پستانی طبیعی می‌شود ولی موهای اندروژن‌وابسته (ابطی/شرمگاهی) بسیار‌کم است، واژن به‌صورت کور انتهایی است و توده‌های اینگوینال معمولاً بیضه‌های نزل‌نکرده‌اند؛ آژنزی مولرین (MRKH) با 46XX می‌آید، ترنر با 45X و تودهٔ اینگوینال ندارد و سندرم Swyer با بلوغ پستانی معمول و تودهٔ تخمدانی اینگوینالی همراه نیست.',
'reasons':['این داده‌ها دقیقاً با AIS سازگارند؛ پاسخ صحیح.','آژنزی مولرین-واژینال با 46XX می‌آید نه 46XY.','ترنر با 45X و بدون تودهٔ اینگوینال دوطرفه می‌آید.','Swyer معمولاً تودهٔ دوطرفه‌ای در کانال اینگوینال ندارد و بلوغ پستانی آن ناقص است.']},
(28,71):{'topic':'epRiskStrongest','lead':'در میان این فهرست، قوی‌ترین عامل خطر برای EP (بارداری خارج‌رحمی) بستن لوله (لیگاسیون لوله) است.',
'interpretation':'هر چهار مورد می‌توانند نقش داشته باشند؛ اما بستن لوله (استریلیزاسیون) در صورت ناکامی، بارداری‌های بعدی را تا حد زیادی به‌صورت خارج‌رحمی جلوه می‌دهد زیرا هر اتصال مجدد، تاخیر حرکت تخم و انسداد ایجاد می‌کند و OR شناخته‌شدهٔ آن برای EP بسیار بالاست؛ سیگار با اثر مزمن بر لوله اثر نسبی کمتری دارد و دوش واژینال و تعداد پارتنر از راه عفونت/بی‌امنی لوله اثر متوسطی دارند اما وزن کلیدی این پرسش با لیگاسیون است.',
'reasons':['سیگار عامل خطر مؤثر اما وزن آن از لیگاسیون کم‌تر است.','بستن لوله در صورت ناکامی قوی‌ترین عامل خطر EP است؛ پاسخ صحیح.','دوش واژینال اثر ضعیف‌تری از راه عفونت دارد.','تعداد پارتنر اثر غیرمستقیم دارد و از وزن کلیدی‌تر نسبت‌به لوله‌بست کم است.']},
(28,72):{'topic':'earlyPregSerialHcg','lead':'تأخیر منس با تست مثبت و سونوگرافی غیرتشخیصی برای بارداری داخل‌رحمی: قدم منطقی چک سری BHCG، نه اقدام تهاجمی یا صرف تکرار زودهنگام سونوگرافی.',
'interpretation':'وقتی تست بارداری مثبت است ولی سونوگرافی هنوز تراک احتمالی ساک را نمی‌بیند، یا بارداری بسیار اولیه است یا EP؛ ارزیابی روند BHCG چارچوب تصمیم را می‌دهد (اگر به آستانهٔ ناحیهٔ تفکیکی برسد سونوگرافی مجدد معنادار است و اگر پلاته یا کاهش بیابد مسیر متفاوت است)؛ نمونه‌برداری آندومتر در این مرحله جایگاه ندارد و لاپاروسکوپی تهاجمی است و تکرار سونوگرافی ۴۸ ساعت بعد بدون مرجع BHCG معمولاً هنوز غیرتشخیصی می‌ماند.',
'reasons':['چک سری BHCG قدم منطقی بعدی است؛ پاسخ صحیح.','نمونه‌برداری آندومتر در این مرحله تهاجمی و زود است.','تکرار سونوگرافی ۴۸ ساعت بعد بدون مرجع تیتر BHCG معمولاً هنوز غیرقطعی می‌ماند.','لاپاروسکوپی فقط در بدترشدن یا یافته‌های خطر آغاز می‌شود.']},
(28,73):{'topic':'gdmEarlyScreen','lead':'بیمار با فاکتور خطر دیابت در بارداری: غربالگری در همین ویزیت (به‌صورت دوپله با تست ۵۰ گرمی یک‌ساعته) شروع شود، نه در ۲۴ هفته.',
'interpretation':'وجود فاکتورهای خطر (سابقهٔ خانوادگی درجهٔ یک دیابت، سابقهٔ GDM، چاقی و...) غربالگری زودهنگام را در ویزیت اول توجیه می‌کند؛ برنامهٔ ایرانی دوپلهٔ ۵۰ گرمی (GCT) در ویزیت اول برای افراد پرخطر پیش‌بینی شده و در صورت بالا بودن به ۱۰۰ گرمی سه‌ساعته می‌رسد و در هفتهٔ ۲۴-۲۸ نیز برای همه (حتی طبیعی‌ها) تکرار می‌شود؛ بنابراین GCT ۵۰ گرمی در همین ویزیت الگوی مناسب است و انتظار تا ۲۴ هفته خطر را می‌پذیرد.',
'reasons':['GTT ۱۰۰ گرمی در ویزیت اول فقط GCT مثبت را تأیید می‌کند.','GCT ۵۰ گرمی ۱۱ هفته در فرد پرخطر درست است؛ پاسخ صحیح.','انتظار تا ۲۴ هفته در پرخطر مناسب نیست و همین‌جا غربالگری شرعی است.','GCT ۵۰ گرمی در ۲۴ هفته جای غربالگری زود در پرخطر را نمی‌گیرد.']},
(28,74):{'topic':'herpesPregTreatment','lead':'ضایعات وزیکولر متعدد و دردناک ژنیتال در بارداری (۳۲ هفته): آسیکلویر خوراکی برای فاز حاد (و در صورت لزوم سرکوب اواخر بارداری).',
'interpretation':'هرپس سیمپلکس ژنیتال حاد با ضایعات وزیکولر دردناک در بارداری با آسیکلویر خوراکی (یا والاسیکلویر) با دوز کامل دوره درمان می‌شود تا طول و شدت حمله کم شود و خطر عود در زایمان و در صورت نیاز تمهید سزارین مهیا شود؛ فامسیکلویر داده‌ی کمتری در بارداری دارد، پنی‌سیلین برای HSV ناکارآمد است و زیدووودین جزو درمان HIV است نه HSV.',
'reasons':['فامسیکلویر گزینهٔ معتبر است ولی در بارداری آسیکلویر داده بیش‌تر دارد و انتخاب اول است.','زیدووودین جزو درمان HIV است و در درمان HSV کاربردی ندارد.','پنی‌سیلین برای عفونت ویروسی هرپس اثری ندارد و درمانی نیست.','آسیکلویر خوراکی در بارداری امن و مؤید است؛ پاسخ صحیح.']},
(28,75):{'topic':'ocpCancerEffects','lead':'قرص‌های ترکیبی خوراکی خطر سرطان آندومتر و تخمدان را کاهش می‌دهند (حفاظت ماندگار) و روی برست/سرویکس اثر حفاظتی ندارند.',
'interpretation':'به‌دلیل حضور پروژسترون، OCP از تحریک بدون‌مقابل استروژن بر آندومتر جلوگیری و خطر سرطان آندومتر را به‌طور ماندگار کاهش می‌دهد و از طریق سرکوب تخمک‌گذاری خطر سرطان اپیتلیال تخمدان را نیز حدود ۴۰-۵۰٪ کم می‌کند؛ این اثر حفاظتی سال‌ها پس از قطع باقی می‌ماند و در برابر برست (حتی ریسک کوچکی گزارش شده) و سرویکس/رودهٔ بزرگ در این چارچوب گفته نمی‌شود.',
'reasons':['برست حتی ممکن است ریسک کوچکی با OCP داشته باشد و حفاظتی نیست.','آندومتر+تخمدان دو سرطانِ دارای اثر حفاظتی مؤید با OCP‌اند؛ پاسخ صحیح.','سرویکس/رودهٔ بزرگ جفت حفاظتی متعارف OCP نیست.','برست همراه با آندومتر حفاظت نمی‌شود (برست محافظت‌نمی‌شود).']},
(28,76):{'topic':'imperforateHymen','lead':'آمنورهٔ اولیه + درد قاعدگیوقت سیکلیک + تودهٔ آبی برجسته در ورودی واژن + تودهٔ فوق‌پوبیک در نوجوان با بلوغ کامل: هایمن بدون سوراخ.',
'interpretation':'در هایمن بدون سوراخ (imperforate hymen) خون قاعدگی پشت پرده جمع می‌شود و کولپوکولپوس/کولپوهماتوکلپوس تشکیل می‌دهد؛ برجستگی آبی‌رنگ غشای هایمن در معاینه (نتیجهٔ فشار خون جمع‌شده) بهعلاوهٔ تودهٔ فوق‌سینفیاژ (رحم/واژن متسع‌شدهٔ مملو از خون) و دردهای سیکلیک بدون بیرون‌زدگی، تقریباً پاتوگنومونیک هایمن بدون سوراخ است؛ آمنورهٔ هیپوتالاموسی و PCOS بدون تودهٔ بالگین‌بوده اند و آژنزی واژن بلوغ پستانی دارد ولی غشای آبی برجسته ندارد.',
'reasons':['آمنورهٔ هیپوتالاموسی با علایم انسدادی و تودهٔ متسع همراه نیست.','PCOS با آنوولوشن و علایم آندروژنی می‌آید نه با علایم انسدادی واژن و تودهٔ خونی.','آژنزی مولرین تودهٔ آبی برجسته در ورودی هایمن ندارد.','هایمن بدون سوراخ با این مشخصه‌ها درست است؛ پاسخ صحیح.']},
(28,77):{'topic':'myomaAsymptomaticObserve','lead':'میوم ساب‌سروزال ۴ سانتی‌متری بدون‌علامت در زن ۴8 ساله: نیاز به اقدام جراحی یا دارویی ندارد و بیمار تحت نظر (سونوگرافی/معاینه دوره‌ای) باقی می‌ماند.',
'interpretation':'در نزدیکی یائسگی بسیاری از میوم‌ها کوچک و ساکن می‌شوند و میوم‌های ساب‌سروزال کم‌تر از همه به خون‌ریزی/فشاری می‌انجامند؛ نیاز به درمان تهاجمی فقط با علایم (خون‌ریزی شدید، درد، رشد سریع، فشردگی ارگان‌ها یا شک بدخیمی) پدید می‌آید؛ بنابراین ارجاع به هیسترکتومی یا میومکتومی در این نقطه افراط است و OCP برای میوم محض درمانی نیست.',
'reasons':['هیسترکتومی شکمی برای میوم ۴ سانتی‌متری بدون‌علامت افراط است.','نظارت و پیگیری دوره‌ای درست است؛ پاسخ صحیح.','OCP فقط می‌تواند در میوم علامت‌دارِ خون‌ریزی نقش داشته باشد نه در میوم بدون‌علامت کوچک.','میومکتومی شکمی در میوم کوچک بدون‌علامت در این سن توجیه نمی‌شود.']},
}
